output_text:
[
  {
    "id": "must_take_cart_from_corral",
    "text": "A shopper is obliged to take the cart from the entrance cart corral before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_corral": "at(1,5)",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "take_cart_from_corral": {
          "pre": {
            "and": [
              "entrance_cart_corral",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_corral"
    }
  },
  {
    "id": "must_return_cart_to_bay",
    "text": "A shopper is obliged to return the cart to the designated bay at cell (0,1) before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "has_shopping_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is forbidden from exiting while still holding or pushing the shopping cart.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "cart_left_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "has_shopping_cart",
          "EXIT"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "A shopper is forbidden from carrying groceries by hand or picking shelf items without a cart.",
    "abstraction": {
      "state_properties": {
        "hands_occupied": "handFull",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "barehanded_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_shopping_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hands_occupied",
          "barehanded_item_pickup"
        ]
      }
    }
  },
  {
    "id": "cart_drop_only_at_return_bay",
    "text": "A shopper is forbidden from leaving the cart anywhere except the cart-return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_carts_at_7_4",
    "text": "Carts are forbidden at cell (7,4), although a shopper without a cart may pass through it.",
    "abstraction": {
      "state_properties": {
        "agent_with_cart_at_7_4": {
          "and": [
            "hasCart",
            "at(7,4)"
          ]
        },
        "parked_cart_at_7_4": "cartAt(7,4)",
        "cart_at_7_4": {
          "or": [
            "agent_with_cart_at_7_4",
            "parked_cart_at_7_4"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_at_7_4"
    }
  },
  {
    "id": "no_cart_east_from_2_5",
    "text": "A shopper pushing a cart is forbidden from moving east out of cell (2,5), but the same movement is allowed after the cart has been returned.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "bottom_aisle_gate": "at(2,5)"
      },
      "events": {
        "cart_moves_east_from_2_5": {
          "pre": {
            "and": [
              "has_shopping_cart",
              "bottom_aisle_gate",
              "E"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_moves_east_from_2_5"
    }
  },
  {
    "id": "eggs_corner_cart_dead_end",
    "text": "When a shopper with a cart reaches the eggs corner at cell (6,4), they are forbidden from continuing east and must instead turn back through the aisle.",
    "abstraction": {
      "state_properties": {
        "eggs_corner": "at(6,4)",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "cart_moves_east_from_eggs_corner": {
          "pre": {
            "and": [
              "eggs_corner",
              "has_shopping_cart",
              "E"
            ]
          },
          "post": "has_shopping_cart"
        },
        "turn_back_west_from_eggs_corner": {
          "pre": {
            "and": [
              "eggs_corner",
              "has_shopping_cart",
              "W"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_moves_east_from_eggs_corner"
    }
  }
]
